import torch
import torch.nn.functional as F
import json

def extract_dt_emb(path):
    ckpt = torch.load(path, map_location='cpu')
    sd = ckpt['agent_state_dict']
    key = '_wm.dynamics._dt_embedding.weight'
    if key not in sd:
        return None
    return sd[key]  # shape [8, 32]

def cos_sim(v1, v2):
    return F.cosine_similarity(v1.unsqueeze(0), v2.unsqueeze(0)).item()

experiments = {
    'exp_008d_civo_trigger_s4': {'label': '008d trained (Walker)', 'type': 'trained'},
    'exp_097_cheetah_008d_s3': {'label': '097 trained (Cheetah)', 'type': 'trained'},
    'exp_100_walker_008a_s1': {'label': '100/008a untrained (Walker)', 'type': 'untrained'},
    'exp_084_frozen_dt_emb_walker_s0': {'label': '084 frozen (Walker)', 'type': 'frozen'},
    'exp_009c_no_dt_emb_s2': {'label': '009c no_dt_emb (Walker)', 'type': 'no_dt_emb'},
    'exp_009d_baseline_walker_s1': {'label': '009d baseline (Walker)', 'type': 'baseline'},
}

base = '/root/autodl-tmp/event-gated-adaptive-horizon/logdir'
results = {}

for exp_name, info in experiments.items():
    path = f'{base}/{exp_name}/latest.pt'
    try:
        emb = extract_dt_emb(path)
        if emb is None:
            print(f'{exp_name}: no dt_embedding found')
            continue

        norms = {f'dt{i+1}_norm': emb[i].norm().item() for i in range(min(4, emb.shape[0]))}
        cosines = {}
        for i in range(min(4, emb.shape[0])):
            for j in range(i+1, min(4, emb.shape[0])):
                cosines[f'dt{i+1}_vs_dt{j+1}'] = cos_sim(emb[i], emb[j])

        results[exp_name] = {
            'label': info['label'],
            'type': info['type'],
            'dt1_vs_dt2': cosines['dt1_vs_dt2'],
            'norms': norms,
            'all_cosines': cosines,
        }
        print(f"{exp_name} ({info['type']}): dt1_vs_dt2 cosine = {cosines['dt1_vs_dt2']:.4f}, "
              f"dt1_norm={norms['dt1_norm']:.4f}, dt2_norm={norms['dt2_norm']:.4f}")
    except Exception as e:
        print(f'{exp_name}: ERROR - {e}')

with open(f'{base}/dt_emb_cosine_current.json', 'w') as f:
    json.dump(results, f, indent=2)
print('\nSaved to dt_emb_cosine_current.json')
PYEOF
